insert into public.dd_research_programs(program_key,program_name,domain,objective,status,release_blocked,green_rule,metadata) values
('SS_BRAND_PUBLIC_TRUST','Shadow & Sol — Brand, Public Trust and Experience','SHADOW_SOL_BRAND_TRUST','Research organizational naming, visual identity, educational/spiritual framing, website, program discovery, volunteer/donor/funder journeys, accessibility, privacy, storytelling, impact reporting, photography/video, SEO, and public claims.','RESEARCHING','t','Public-facing claims about nonprofit status, outcomes, history, safety, education, health/wellness, cultural traditions, grants, property, or partnerships require evidence appropriate to the claim.','{"entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "target_project_ref": "yxhbernpesgzvfdoubyd", "name_variants_to_reconcile": ["Shadow & Sol", "Sol and Shadow Collective", "Sol & Shadow Collective"]}'::jsonb),
('SS_CROSS_ENTITY_DANI','Shadow & Sol ↔ DANI Related-Party Architecture','CROSS_ENTITY','Research lawful, documented, arm''s-length collaboration between Shadow & Sol and DANI DECLARES while preserving charitable purpose, commercial integrity, books, assets, data, governance, and fair-market-value controls.','RESEARCHING','t','DANI is treated as a related party whenever legally applicable; no shared service, asset, property, personnel, IP, sponsorship, reimbursement, procurement, or payment is authorized by research alone.','{"entity_scope": "CROSS_ENTITY", "staging_host": "DANI_TESTER", "related_party": "DANI DECLARES LLC", "separate_data": true, "separate_books": true, "target_project_ref": "yxhbernpesgzvfdoubyd"}'::jsonb),
('SS_FIELD_SCHOOL_MODEL','Shadow & Sol — Field School / Learning Experience Model','SHADOW_SOL_PROGRAM_MODEL','Determine the lawful and mission-fit structure for field-school, class, workshop, camp, glamping, retreat, enrichment, family, youth, and adult learning experiences.','RESEARCHING','t','No program may be labeled or operated as a school, child-care program, camp, lodging program, therapeutic program, or regulated educational service until classification and jurisdiction-specific requirements are evidenced.','{"concepts": ["field_school", "classes", "workshops", "glamping", "seasonal_learning", "family_learning", "youth_learning", "adult_learning"], "entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "target_project_ref": "yxhbernpesgzvfdoubyd"}'::jsonb),
('SS_FINANCE_EARNED_REVENUE','Shadow & Sol — Nonprofit Finance and Earned Revenue','SHADOW_SOL_FINANCE','Research nonprofit accounting, restricted/unrestricted funds, donations, grants, program revenue, fundraising/admin/program cost treatment, earned-revenue models, UBIT, sales/use tax, and related-party cost allocation.','RESEARCHING','t','No revenue model, restricted-fund use, reimbursement, allocation, compensation, DANI payment, or earned-income stream becomes governed authority without accounting/legal evidence and approval.','{"entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "target_project_ref": "yxhbernpesgzvfdoubyd", "finance_separation_required": true}'::jsonb),
('SS_FOUNDATION_GOVERNANCE','Shadow & Sol — Formation and Governance','SHADOW_SOL_FOUNDATION','Establish authoritative research for nonprofit formation, 501(c)(3) eligibility, board governance, conflicts, filings, charitable solicitation, and governance authority.','RESEARCHING','t','No formation, tax-exemption, solicitation, board, compensation, contract, or related-party authority becomes operational without primary-source evidence and required human/governance approval.','{"entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "nonprofit_native": true, "target_project_ref": "yxhbernpesgzvfdoubyd", "migration_when_available": true}'::jsonb),
('SS_FUNDING_CAPITAL','Shadow & Sol — Funding, Grants and Capital','SHADOW_SOL_FUNDING','Continuously research nonprofit funding for formation, programs, agriculture, environmental education, youth/family education, community development, land, facilities, gardens, greenhouses, equipment, and educational infrastructure.','RESEARCHING','t','A discovered opportunity is never marked eligible solely because it appears in search; eligibility, geography, entity status, match, restrictions, allowable costs, deadline, and primary NOFO/funder evidence are required.','{"entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "target_project_ref": "yxhbernpesgzvfdoubyd", "continuous_research": true}'::jsonb),
('SS_GEOGRAPHY_GA_SC','Shadow & Sol — Georgia / South Carolina Geography','SHADOW_SOL_GEOGRAPHY','Research Georgia launch requirements and future South Carolina activity, with Piedmont/Greenville-area community, land, partnership, school, agriculture, environmental, funding, facility, and registration questions handled independently from DANI.','RESEARCHING','t','No DANI foreign-LLC conclusion is reused as nonprofit authority; Shadow & Sol registration, charitable solicitation, land-use, program, tax, and facility obligations must be researched independently.','{"sc_anchor": "Piedmont/Greenville area", "entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "jurisdictions": ["GA", "SC"], "target_project_ref": "yxhbernpesgzvfdoubyd"}'::jsonb),
('SS_PEOPLE_SAFETY','Shadow & Sol — People, Youth Safety, Risk and Insurance','SHADOW_SOL_PEOPLE_SAFETY','Research directors, officers, employees, contractors, volunteers, instructors, interns, participant safeguards, screening, training, insurance, outdoor/tool/fire/food/plant/weather/emergency risk, and incident controls.','RESEARCHING','t','Unknown screening, supervision, insurance, youth-safety, instructor qualification, emergency, or activity-risk requirements remain REVIEW REQUIRED; absence of records never means approved.','{"fail_closed": true, "entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "target_project_ref": "yxhbernpesgzvfdoubyd"}'::jsonb),
('SS_PROGRAM_PORTFOLIO','Shadow & Sol — Mission Program Portfolio','SHADOW_SOL_PROGRAMS','Research community-need, charitable fit, program design, outcomes, and evidence standards for land-based education, gardening, propagation, herbal/plant education, stewardship, nature, wellness-oriented community learning, and practical skills.','RESEARCHING','t','A concept becomes a program candidate only after mission fit, community need, safety, legal classification, budget, funding, accessibility, and impact-measurement requirements are evidenced.','{"entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "target_project_ref": "yxhbernpesgzvfdoubyd"}'::jsonb),
('SS_PROPERTY_FACILITIES','Shadow & Sol — Land, Property and Facilities','SHADOW_SOL_PROPERTY','Research lawful charitable ownership, lease, donated-use, shared-use, mixed-use, garden, greenhouse, classroom, workshop, lodging/glamping, stewardship, and facility models in Georgia and South Carolina.','RESEARCHING','t','No property acquisition, lease, residential use, mixed use, facility opening, or related-party property arrangement advances without zoning/use, tax, insurance, safety, funding, FMV, title, and governance evidence.','{"entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "jurisdictions": ["GA", "SC"], "target_project_ref": "yxhbernpesgzvfdoubyd"}'::jsonb),
('SS_RESEARCH_GOVERNANCE','Shadow & Sol — Research Governance and Self-Audit','SHADOW_SOL_RESEARCH_GOVERNANCE','Create the nonprofit-native intelligence discipline: source hierarchy, evidence provenance, confidence, freshness, conflict reconciliation, blind-spot discovery, governance attention, change traceability, and research-to-action separation.','RESEARCHING','t','Automated checks may establish OBSERVED/CANDIDATE evidence only; CONFIRMED or policy-authoritative status requires source-appropriate reconciliation and must never be inferred from a missing record or expected-signal match alone.','{"entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "target_project_ref": "yxhbernpesgzvfdoubyd", "no_auto_confirmation": true, "research_self_governance": true}'::jsonb),
('SS_SEASONAL_RND','Shadow & Sol — 365-Day Seasonal R&D and Curriculum','SHADOW_SOL_CURRICULUM_RND','Treat the 365-day founder field journey and seasonal dossiers/grimoires as a governed R&D system for future curriculum, kits, experiences, replacement components, and evidence-based program design.','RESEARCHING','t','Prototype practice, spiritual framing, field observations, and user experience notes remain R&D evidence until factual claims, safety, charitable fit, curriculum use, and public-facing representations are reviewed.','{"rnd_year": true, "entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "prototype_assets": ["Litha Grimoire", "seasonal field dossiers", "365-day field journey"], "target_project_ref": "yxhbernpesgzvfdoubyd"}'::jsonb),
('SS_TECH_DATA_SECURITY','Shadow & Sol — Technology, Data and Security','SHADOW_SOL_TECH_SECURITY','Research least-privilege architecture, RLS, roles, donor/participant/youth data minimization, privacy, consent, secrets, audit logs, backups, incident response, AI governance, automation limits, and external-action safety.','RESEARCHING','t','Research may prepare external actions but may not file, publish, send, spend, contract, grant access, or alter organizational authority without an explicit approved policy and auditable receipt.','{"entity_scope": "SHADOW_SOL_ONLY", "staging_host": "DANI_TESTER", "target_project_ref": "yxhbernpesgzvfdoubyd", "high_impact_actions_gated": true}'::jsonb)
