-- Shadow & Sol research staging seed. Research-only in DANI tester while target project yxhbernpesgzvfdoubyd is inactive.

on conflict(program_key) do update set program_name=excluded.program_name,domain=excluded.domain,objective=excluded.objective,status=excluded.status,release_blocked=excluded.release_blocked,green_rule=excluded.green_rule,metadata=public.dd_research_programs.metadata||excluded.metadata,updated_at=now();

on conflict(work_key) do update set program_key=excluded.program_key,question=excluded.question,required_evidence=excluded.required_evidence,priority=excluded.priority,status=case when public.dd_research_work_queue.status='GREEN' then public.dd_research_work_queue.status else excluded.status end,blocker=excluded.blocker,next_action=excluded.next_action,owner_decision_required=excluded.owner_decision_required,metadata=public.dd_research_work_queue.metadata||excluded.metadata,updated_at=now();

on conflict(source_key) do update set program_key=excluded.program_key,work_key=excluded.work_key,source_title=excluded.source_title,source_url=excluded.source_url,authority_level=excluded.authority_level,temporal_class=excluded.temporal_class,status=excluded.status,check_interval_minutes=excluded.check_interval_minutes,expected_signals=excluded.expected_signals,metadata=public.dd_research_sources.metadata||excluded.metadata,updated_at=now();

on conflict(domain) do update set auto_research=excluded.auto_research,auto_reconcile_low_risk=excluded.auto_reconcile_low_risk,owner_required_actions=excluded.owner_required_actions,stale_behavior=excluded.stale_behavior,notes=excluded.notes,updated_at=now();

update public.dd_research_work_queue set metadata=metadata||jsonb_build_object('entity_scope',case when work_key in ('EA_SC_636_HWY17_DILIGENCE','EA_SC_FLEX_PROPERTY','EA_SC_FOREIGN_LLC','EA_SC_LIVE_WORK','EA_SC_PIEDMONT_MARKET_ECONOMICS','EA_SC_PIEDMONT_PROPERTY_SEARCH','EA_SC_PIEDMONT_SERVICE_RADIUS','EA_SC_TAX_ACCOUNTS') then 'DANI_ONLY' when work_key in ('EA_LAND_OWNERSHIP_USE','EA_SC_INTERENTITY') then 'CROSS_ENTITY' else 'SHADOW_SOL_ONLY' end) where program_key='ENTITY_ARCHITECTURE';